//这里配置你的被动扫描代理地址
proxy = "http://127.0.0.1:7777"

send = func(origin /* string */) {
    host = poc.ParseBytesToHTTPRequest(origin)~.Host
    is_https = str.IsTLSServer(host)
    rsp, req = poc.HTTP(origin, poc.https(is_https), poc.connectTimeout(5), poc.proxy(proxy))~
    return string(rsp)
}

sends = func(origin /* string */) {
    origin = string(origin)
    inputs = make([]int, 0, 100)
    if origin.Contains(",") {
        inputs = str.Split(origin, ",").Map(i => { return atoi(i.Trim())~ })
    } else {
        inputs.Push(atoi(origin)~)
    }

    for flow in db.QueryHTTPFlowsByID(inputs...) {
        rsp, req = poc.HTTP(flow.GetRequest(), poc.https(flow.IsHTTPS), poc.connectTimeout(5), poc.proxy(proxy))~
    }


    return inputs
}

handle = func(origin /* string */) {
    info = ''
    if str.StringContainsAnyOfSubString(origin, ["HTTP", "Host"]) {
        info = "传入的可能是数据包"
        return send(origin)
    } else {
        info = "传入的可能是数据包id"
        return sends(origin)
    }
}
